import { inject, Injectable } from '@angular/core';
import { BsModalService } from 'ngx-bootstrap/modal';
import { FocusableChildren } from '../api';

@Injectable()
export class PlaceholderService {
	private dropdownDirective?: FocusableChildren;
	private lastFocusedElement?: HTMLElement;
	private dropdownButton?: HTMLElement;
	private index?: number;

	private bsModalService = inject(BsModalService);

	constructor() {
		this.bsModalService.onShow.subscribe(() => {
			this.saveFocusLocation();
		});
		this.bsModalService.onHidden.subscribe(() => {
			this.resume();
		});
	}

	public saveFocusLocation(dropdownButton?: HTMLElement, dropdownDirective?: FocusableChildren): void {
		this.lastFocusedElement = document.activeElement as HTMLElement;
		if (dropdownButton) {
			this.dropdownButton = dropdownButton;
			this.dropdownDirective = dropdownDirective;
			this.index = dropdownDirective?.indexOf(this.lastFocusedElement);
		}
	}

	public deleteFocusLocation(): void {
		this.dropdownButton = undefined;
		this.lastFocusedElement = undefined;
	}

	public resume(): void {
		const dropdownButton = this.dropdownButton;
		const dropdownDirective = this.dropdownDirective;
		const index = this.index;
		this.dropdownButton = undefined;
		this.dropdownDirective = undefined;
		this.index = undefined;
		if (dropdownButton && document.body.contains(dropdownButton)) {
			dropdownButton.click();
		}
		setTimeout(() => {
			if (index !== undefined && index !== -1) {
				dropdownDirective?.focusOnIndex(index);
			} else if (this.lastFocusedElement && document.body.contains(this.lastFocusedElement)) {
				this.lastFocusedElement.focus();
			}
			this.lastFocusedElement = undefined;
		});
	}
}